const fs = require('fs'), crypto = require('crypto');
const root = 'products/services/inventory-file-qa-subcontract/';
const result = {};
for (const name of ['sba-subnet.html', 'sba-subnet-inventory.html']) {
  const raw = fs.readFileSync(root + 'raw/' + name);
  const page = raw.toString('utf8');
  const clean = value => value.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const fields = (page.match(/<input\b[^>]*>/gi) || []).filter(tag => /name=["']keyword["']/i.test(tag));
  const bodies = Array.from(page.matchAll(/<tbody\b[^>]*>([\s\S]*?)<\/tbody>/gi), m => m[1]);
  const rows = bodies.flatMap(body => Array.from(body.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi), m => clean(m[1])));
  const notices = (page.match(/>[^<>]*(?:no results|no opportunities|no records|no matching)[^<>]*</gi) || []).map(s => s.slice(1,-1).trim());
  result[name] = {sha256: crypto.createHash('sha256').update(raw).digest('hex'), keyword_fields: fields, row_count: rows.length, row_examples: rows.slice(0,3).map(x=>x.slice(0,250)), no_results_text: notices.slice(0,5)};
}
const output = JSON.stringify(result,null,2) + '\n';
fs.writeFileSync(root+'director-subnet-inventory-filter.json',output);
console.log(output);
